<?php declare(strict_types=1);$financeMatchMessages??=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];$financeMatchText??=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\FinanceMatchingMessages::text($source,$financeMatchMessages,$values);$allocationReturnKinds=[];$allocationReturnMessages=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];$allocationReturnText=static fn(string $value):string=>\Kulturhus\Native\Language\FinanceBankMessages::text($value,$allocationReturnMessages); ?>
<?php $allocationFunding=[];$allocationFundingError='';try{$allocationIsTransaction=($allocationReturn??'')==='transaction';$allocationFunding=$finance->allocationFundingHistory($allocationIsTransaction?$t['id']:$r['id'],$allocationIsTransaction);}catch(DomainException $failure){$allocationFundingError=$failure->getMessage();}?>
<section class="card"><h2><?= e($financeMatchText('Zuordnungen & Verlauf')) ?></h2>
<?php if($allocationFundingError!==''):?><p class="error" role="alert"><?=e($allocationReturnText($allocationFundingError))?></p><?php endif?>
<?php if(!$allocationRows): ?><p class="muted"><?= e($financeMatchText('Noch keine Zuordnung vorhanden.')) ?></p><?php endif ?>
