<div class="allocation-history-row" data-finance-allocation="<?= e($l['id']) ?>">
 <div><a class="profile-link" href="<?= e(url(array_replace(receiptPaymentContext($l['entry_id'],$_GET),['candidate'=>$l['transaction_id'],'match_account'=>$l['account_id']]))) ?>"><?= e(($l['display_number']??sprintf('KH-%05d',$l['number'])).' · '.$l['entry_description']) ?></a>
 <a class="muted" href="<?= e(url(bankTransactionContext($l['transaction_id'],$_GET))) ?>"><?= e(dateDe($l['booked_on']).' · '.$l['account_name'].' · '.$l['transaction_description']) ?></a></div>
 <strong class="amount"><?= e(euro((int)$l['cents'])) ?></strong><?php if($fundingState=$allocationFunding[$l['id']]??null):?><div class="wide" data-allocation-funding="<?=e($l['id'])?>"><?php if($fundingState['returned_cents']>0):?><p><?=e($allocationReturnText('Ursprünglich zugeordnet').': '.euro($fundingState['original_cents']).' · '.$allocationReturnText('Davon zurückgekommen').': '.euro($fundingState['returned_cents']).' · '.$allocationReturnText('Davon noch bezahlt').': '.euro($fundingState['paid_cents']))?></p><?php foreach($fundingState['returns']as$return):?><a class="btn btn-outline theme-secondary" data-allocation-refund href="<?=e(url(array_replace(bankTransactionContext($return['counter_id'],$_GET),['account'=>$return['counter_account_id']])))?>"><?=e($allocationReturnText($return['native_debit']?'Rücklastschrift und Finanzzuordnung öffnen':'Tatsächliche Rückzahlung und Zuordnung öffnen').' · '.euro($return['cents']))?></a><?php endforeach;endif?><?php if($fundingState['execution']):?><p><?=e($allocationReturnText('Diese ursprüngliche Zuordnung belegt eine bestätigte Bankausführung. Den Ausführungsnachweis zuerst prüfen.'))?></p><?php endif?><p class="muted"><?=e($allocationReturnText('Die ursprüngliche Zahlungszuordnung bleibt erhalten. Eine falsche Rückzahlungs- oder Auftragszuordnung über ihren eigenen Zusammenhang prüfen.'))?></p></div><?php endif?>
 <?php if($l['voided_at']): ?><p class="muted wide"><?= e($financeMatchText('Aufgehoben ·')) ?> <?= e($l['void_reason']) ?></p>
 <?php elseif($l['reversed_on']):$allocationReturnKinds[$l['transaction_id']]??=($allocationReturn??'')==='transaction'&&isset($transactionPaymentReturns)?(bool)$transactionPaymentReturns:(bool)$finance->paymentReturnHistory($l['transaction_id']); ?><p class="muted wide"><?= e($allocationReturnText($allocationReturnKinds[$l['transaction_id']]?'Zahlung zurückgekommen am':'Gegenbuchung am').' '.dateDe($l['reversed_on'])) ?></p>
 <?php elseif($finance->canWrite()&&$allocationFundingError===''&&!isset($allocationFunding[$l['id']])): ?><details class="wide" <?= $releasePosted?'open':'' ?>><summary><?= e($financeMatchText('Zuordnung aufheben')) ?></summary><p class="muted"><?= e($financeMatchText('Der Betrag wird wieder zur Zuordnung frei. Der Kontostand bleibt unverändert.')) ?></p>
 <?php if($releaseReviewed): ?><p class="notice" role="status"><?= e($financeMatchText('Aktueller Stand neu gelesen. Grund und Zuordnung prüfen und das Aufheben anschließend gesondert bestätigen.')) ?></p><?php elseif($releasePosted): ?><p class="muted"><?= e($financeMatchText('Dein Korrekturgrund und der ursprünglich geprüfte Stand sind erhalten. Bei einer zwischenzeitlichen Änderung zuerst „Aktuellen Stand prüfen“ wählen.')) ?></p><?php endif ?>
 <form method="post" class="filter-form">
 <?= csrf().hidden('action','release-allocation').hidden('id',$l['id']).hidden('transaction_id',$l['transaction_id']).hidden('entry_id',$l['entry_id']).hidden('transaction_version',$releasePosted&&!$releaseReviewed?input($_POST,'transaction_version'):$l['transaction_version']).hidden('entry_version',$releasePosted&&!$releaseReviewed?input($_POST,'entry_version'):$l['entry_version']).hidden('return_to',$allocationReturn) ?>
 <label><?= e($financeMatchText('Grund')) ?><input aria-label="<?= e($financeMatchText('Grund')) ?>" aria-describedby="allocation-reason-help-<?= e($l['id']) ?>" class="form-control" name="reason" maxlength="1000" required value="<?= e($releasePosted?input($_POST,'reason'):'') ?>"><small id="allocation-reason-help-<?= e($l['id']) ?>"><?= e($financeMatchText('Höchstens 500 Zeichen.')) ?></small></label><button class="btn btn-outline theme-secondary secondary"><?= e($financeMatchText('Zuordnung aufheben')) ?></button><button class="btn btn-outline theme-secondary secondary" name="review_allocation" value="1" formnovalidate><?= e($financeMatchText('Aktuellen Stand prüfen')) ?></button></form></details><?php endif ?>
</div><?php endforeach ?></section>
